263	// ----- Failure: strict textual format --------------------------------------
264	
265	#[test]
266	fn noncanonical_time_syntax_fails_in_either_field() {
267	    // Seconds are mandatory, the value must end in 'Z' (UTC only), digits
268	    // must be digits, and the tag must actually be a time type. Each input
269	    // is wrapped in a well-formed TLV so structural parsing succeeds and
270	    // rejection comes from time decoding itself.
271	    let cases: &[(u8, &[u8])] = &[
272	        // UTCTime
273	        (TAG_UTC_TIME, b""),                 // empty
274	        (TAG_UTC_TIME, b"2601150930Z"),      // seconds omitted
275	        (TAG_UTC_TIME, b"260115093000"),     // no trailing Z
276	        (TAG_UTC_TIME, b"260115093000z"),    // lowercase z
277	        (TAG_UTC_TIME, b"26011509300aZ"),    // non-digit character
278	        (TAG_UTC_TIME, b"26011509 000Z"),    // space among the digits
279	        (TAG_UTC_TIME, b"260115093000+0000"),// explicit offset instead of Z
280	        (TAG_UTC_TIME, b"260115093000-0800"),// negative offset
281	        (TAG_UTC_TIME, b"260115093000.0Z"),  // fractional seconds
282	        (TAG_UTC_TIME, b"260115093000Z "),   // trailing byte after Z
283	        (TAG_UTC_TIME, b"20260115093000Z"),  // four-digit year under UTCTime
284	        // GeneralizedTime
285	        (TAG_GENERALIZED_TIME, b""),                   // empty
286	        (TAG_GENERALIZED_TIME, b"202601150930Z"),      // seconds omitted
287	        (TAG_GENERALIZED_TIME, b"20260115093000"),     // no trailing Z
288	        (TAG_GENERALIZED_TIME, b"20260115093000z"),   // lowercase z
289	        (TAG_GENERALIZED_TIME, b"2026011509300aZ"),   // non-digit character
290	        (TAG_GENERALIZED_TIME, b"20260115093000+0000"),// offset instead of Z
291	        (TAG_GENERALIZED_TIME, b"20260115093000.5Z"), // fractional seconds
292	        (TAG_GENERALIZED_TIME, b"260115093000Z"),     // two-digit year under GeneralizedTime
293	        // Other universal types are not Time alternatives.
294	        (0x16, b"260115093000Z"), // IA5String
295	        (0x1A, b"260115093000Z"), // VisibleString
296	        (0x04, b"20260115093000Z"), // OCTET STRING
297	    ];
298	    for (i, &(tag, text)) in cases.iter().enumerate() {
299	        let bad = tlv(tag, text);
300	        let cert = default_cert(&bad, &good_na());
301	        let (out, _cert) = run_inspect(&format!("badfmt-before-{i}"), &cert);
302	        assert_invalid_certificate(&out);
303	
304	        let cert = default_cert(&good_nb(), &bad);
305	        let (out, _cert) = run_inspect(&format!("badfmt-after-{i}"), &cert);
