310	#[test]
311	fn truncated_time_content_fails_in_either_field() {
312	    // The TLV length announces 30 content bytes but only eight follow; the
313	    // enclosing validity SEQUENCE is itself correctly bounded, so the error
314	    // is the truncated time, in first or second position.
315	    let short = raw_tlv(TAG_UTC_TIME, &[0x1E], b"26011509");
316	
317	    let validity = seq(&concat(&[&short, &good_na()]));
318	    let (out, _cert) = run_inspect("trunc-before", &default_cert_validity(&validity));
319	    assert_invalid_certificate(&out);
320	
321	    let validity = seq(&concat(&[&good_nb(), &short]));
322	    let (out, _cert) = run_inspect("trunc-after", &default_cert_validity(&validity));
323	    assert_invalid_certificate(&out);
324	}
325	
326	// ----- Assertions / process plumbing --------------------------------------
327	
328	/// A successful inspect must show all five fields in the fixed order with the
329	/// fixed name and serial values — time encodings never influence them — and
330	/// must leave stderr empty.
331	fn assert_times_success(out: &Output, not_before: &str, not_after: &str) {
332	    assert_eq!(out.status.code(), Some(0), "stderr={}", lossy(&out.stderr));
333	    assert!(out.stderr.is_empty(), "stderr={}", lossy(&out.stderr));
334	    assert_eq!(
335	        lossy(&out.stdout),
336	        format!(
337	            "Subject: {FIXED_SUBJECT}\n\
338	             Issuer: {FIXED_ISSUER}\n\
339	             Serial Number: {FIXED_SERIAL}\n\
340	             Not Before: {not_before}\n\
341	             Not After: {not_after}\n"
342	        )
343	    );
344	}
345	
346	/// Every malformed-input case shares the documented contract: exit code 2,
347	/// nothing on stdout (so neither a name nor the other, valid time field is
348	/// printed first), and the fixed invalid-certificate prefix on stderr with a
349	/// non-empty reason after it.
350	fn assert_invalid_certificate(out: &Output) {
351	    assert_eq!(
352	        out.status.code(),
353	        Some(2),
354	        "stdout={} stderr={}",
355	        lossy(&out.stdout),
356	        lossy(&out.stderr)
357	    );
358	    assert!(
359	        out.stdout.is_empty(),
360	        "stdout must be empty on failure, got: {}",
361	        lossy(&out.stdout)
362	    );
363	    let stderr = lossy(&out.stderr);
364	    assert!(
365	        stderr.starts_with("chainview: invalid DER certificate: "),
366	        "unexpected stderr: {stderr}"
367	    );
368	    assert!(
369	        stderr["chainview: invalid DER certificate: ".len()..].trim().len() > 1,
370	        "missing error reason in stderr: {stderr}"
371	    );
372	}
373	
374	fn lossy(bytes: &[u8]) -> String {
375	    String::from_utf8_lossy(bytes).into_owned()
376	}
377	
378	fn run_inspect(tag: &str, data: &[u8]) -> (Output, TempCert) {
379	    let cert = TempCert::new(tag, data);
380	    let output = Command::new(env!("CARGO_BIN_EXE_chainview"))
381	        .arg("inspect")
382	        .arg(&cert.path)
383	        .output()
384	        .expect("running chainview");
385	    (output, cert)
386	}
387	
388	fn run_inspect_with_tz(tag: &str, data: &[u8], tz: Option<&str>) -> Output {
389	    let cert = TempCert::new(tag, data);
390	    let mut cmd = Command::new(env!("CARGO_BIN_EXE_chainview"));
391	    cmd.arg("inspect").arg(&cert.path);
392	    match tz {
393	        Some(zone) => {
394	            cmd.env("TZ", zone);
395	        }
396	        None => {
397	            cmd.env_remove("TZ");
398	        }
399	    }
400	    cmd.output().expect("running chainview")
401	}
402	
403	struct TempCert {
404	    path: PathBuf,
405	}
406	
407	impl TempCert {
408	    fn new(tag: &str, data: &[u8]) -> Self {
409	        static COUNTER: AtomicU64 = AtomicU64::new(0);
410	        let unique = COUNTER.fetch_add(1, Ordering::Relaxed);
411	        let path = std::env::temp_dir().join(format!(
412	            "chainview-validity-test-{}-{tag}-{unique}.der",
413	            std::process::id()
414	        ));
415	        fs::write(&path, data).expect("writing temp certificate");
416	        TempCert { path }
417	    }
418	}
419	
420	impl Drop for TempCert {
421	    fn drop(&mut self) {
422	        let _ = fs::remove_file(&self.path);
423	    }
424	}
425	
426	// ----- Certificate / DER construction -------------------------------------
427	//
428	// Mirrors the constructor in tests/name_display.rs: minimal DER lengths
429	// everywhere, except where a test injects hand-written length bytes to
430	// exercise truncation.
431	
432	fn utc(text: &[u8]) -> Vec<u8> {
433	    tlv(TAG_UTC_TIME, text)
434	}
435	
436	fn generalized(text: &[u8]) -> Vec<u8> {
437	    tlv(TAG_GENERALIZED_TIME, text)
438	}
439	
440	/// Valid counterpart field used when only one time is being corrupted:
441	/// 2030-01-01T00:00:00Z / 2031-01-01T00:00:00Z in UTCTime.
442	fn good_nb() -> Vec<u8> {
443	    utc(b"300101000000Z")
444	}
445	
446	fn good_na() -> Vec<u8> {
447	    utc(b"310101000000Z")
448	}
449	
450	fn default_cert(not_before: &[u8], not_after: &[u8]) -> Vec<u8> {
451	    let validity = seq(&concat(&[not_before, not_after]));
452	    default_cert_validity(&validity)
453	}
454	
455	fn default_cert_validity(validity: &[u8]) -> Vec<u8> {
456	    build_cert(
457	        &simple_cn_name("example.com"),
458	        &simple_cn_name("Test CA"),
459	        validity,
460	    )
461	}
462	
463	/// Assemble a complete, parseable v1 DER certificate with fixed serial and
464	/// key material around the supplied Subject/Issuer names and validity TLV.
465	fn build_cert(subject: &[u8], issuer: &[u8], validity: &[u8]) -> Vec<u8> {
466	    let serial = tlv(0x02, &[0x0E, 0x8A, 0x4C, 0x2F, 0x9B, 0x17, 0xD6, 0x03]);
467	    let spki = seq(&concat(&[
468	        &seq(&concat(&[&oid(&[1, 2, 840, 113549, 1, 1, 1]), &tlv(0x05, &[])])),
469	        &tlv(0x03, &[0x00, 0x01, 0x00]), // BIT STRING, zero unused bits
470	    ]));
471	
472	    let tbs = seq(&concat(&[
473	        &serial,
474	        &signature_algorithm(),
475	        issuer,
476	        validity,
477	        subject,
478	        &spki,
479	    ]));
480	    seq(&concat(&[&tbs, &signature_algorithm(), &tlv(0x03, &[0x00])]))
481	}
482	
483	fn signature_algorithm() -> Vec<u8> {
484	    // sha256WithRSAEncryption with explicit NULL parameters.
485	    seq(&concat(&[&oid(&[1, 2, 840, 113549, 1, 1, 11]), &tlv(0x05, &[])]))
486	}
487	
488	fn simple_cn_name(cn: &str) -> Vec<u8> {
489	    let atv = seq(&concat(&[&oid(CN), &tlv(0x0C, cn.as_bytes())]));
490	    let rdn = tlv(0x31, &atv); // SET { CN=... }
491	    tlv(0x30, &rdn) // SEQUENCE { RDN }
492	}
493	
494	/// TLV with caller-supplied length bytes; used to forge truncated contents.
495	fn raw_tlv(tag: u8, len_bytes: &[u8], content: &[u8]) -> Vec<u8> {
496	    let mut out = vec![tag];
497	    out.extend_from_slice(len_bytes);
498	    out.extend_from_slice(content);
499	    out
500	}
501	
502	fn oid(arcs: &[u64]) -> Vec<u8> {
503	    assert!(arcs.len() >= 2);
504	    let mut content = oid_arc(arcs[0] * 40 + arcs[1]);
505	    for &arc in &arcs[2..] {
506	        content.extend_from_slice(&oid_arc(arc));
507	    }
508	    tlv(0x06, &content)
509	}
510	
511	fn oid_arc(mut value: u64) -> Vec<u8> {
512	    let mut out = vec![(value % 128) as u8];
513	    value /= 128;
514	    while value > 0 {
515	        out.push(0x80 | (value % 128) as u8);
516	        value /= 128;
517	    }
518	    out.reverse();
519	    out
520	}
521	
522	fn seq(content: &[u8]) -> Vec<u8> {
523	    tlv(0x30, content)
524	}
525	
526	fn tlv(tag: u8, content: &[u8]) -> Vec<u8> {
527	    let mut out = vec![tag];
528	    out.extend_from_slice(&der_len(content.len()));
529	    out.extend_from_slice(content);
530	    out
531	}
532	
533	fn der_len(n: usize) -> Vec<u8> {
534	    if n < 0x80 {
535	        vec![n as u8]
536	    } else {
537	        let mut body = Vec::new();
538	        let mut v = n;
539	        while v > 0 {
540	            body.push((v & 0xFF) as u8);
541	            v >>= 8;
542	        }
543	        body.reverse();
544	        let mut out = vec![0x80 | body.len() as u8];
545	        out.extend_from_slice(&body);
546	        out
547	    }
548	}
549	
550	fn concat(parts: &[&[u8]]) -> Vec<u8> {
551	    let mut out = Vec::new();
552	    for part in parts {
553	        out.extend_from_slice(part);
554	    }
555	    out
556	}
